<template>
  <v-container class="pt-0">
    <v-card class="c-simple-card pa-4">
      <ProductList></ProductList>
      <v-card-text>
        <v-alert class="mb-6" v-if="checkoutError" type="warning" dense>{{ checkoutError }}</v-alert>
        <div class="mb-0">
          <v-btn-toggle
              selected-class="text-primary"
              divided
              variant="plain"
              v-model="text_style"
              class="c-button-list"
          >
            <v-btn
                v-for="tag in tags"
                :text="tag"
                :value="tag"
            ></v-btn>
          </v-btn-toggle>
          <v-checkbox
              v-model="show_icons"
              :color="colors.primary"
              hide-details
              label="Show Icons">
          </v-checkbox>
        </div>
        <v-form class="checkout-form" ref="paymentForm" v-model="valid">
          <div class="border-1">
            <v-text-field
                v-model="cardNumber"
                name="card_number"
                label="Card Number"
                placeholder="4444 5555 6666 1111"
                @input="formatCardNumber"
                :error-messages="cardNumberError"
                maxlength="19"
                required
                :variant="text_style"
                :prepend-inner-icon="show_icons ? 'mdi-credit-card' : ''"
                class="pb-4"
            ></v-text-field>

            <v-row class="pb-3">
              <v-col cols="6">
                <v-text-field
                    v-model="expiryDate"
                    label="Expiration Date (MM/YY)"
                    placeholder="12/35"
                    @input="formatExpiryDate"
                    :error-messages="expiryDateError"
                    maxlength="5"
                    required
                    :variant="text_style"
                    :prepend-inner-icon="show_icons ? 'mdi-calendar' : ''"
                ></v-text-field>
              </v-col>
              <v-col cols="6">
                <v-text-field
                    v-model="cvv"
                    label="CVV"
                    name="cvv2"
                    @input="formatCVV"
                    :error-messages="cvvError"
                    maxlength="4"
                    required
                    :variant="text_style"
                    :prepend-inner-icon="show_icons ? 'mdi-lock' : ''"
                ></v-text-field>
              </v-col>
            </v-row>
          </div>

          <v-btn :disabled="!valid" :color="colors.primary" block @click="handleSubmit">
            Pay Now
          </v-btn>
        </v-form>
      </v-card-text>
    </v-card>
  </v-container>
</template>
<script>
import colors from "@/utils/colors";
import ProductList from "@/components/products/ProductList.vue";
import $checkout from 'ipsp-js-sdk';

export default {
  name: "SimpleCardWidget",
  components: {ProductList},
  computed: {
    colors() {
      return colors
    }
  },
  props: {
    amount: 0,
  },
  data() {
    return {
      valid: false,
      show_icons: true,
      text_style: "outlined",
      cardNumber: "",
      expiryDate: "",
      cvv: "",
      cardNumberError: "",
      expiryDateError: "",
      cvvError: "",
      checkoutError: "",
      tags: [
        'filled',
        'outlined',
        'underlined',
        'solo',
      ],
    };
  },
  methods: {
    formatCardNumber() {
      this.cardNumber = this.cardNumber.replace(/\D/g, "").replace(/(.{4})/g, "$1 ").trim();
      this.validateCardNumber();
    },
    formatExpiryDate() {
      this.expiryDate = this.expiryDate
          .replace(/\D/g, "")
          .replace(/^(\d{2})(\d{0,2})/, "$1/$2")
          .slice(0, 5);
      this.validateExpiryDate();
    },
    formatCVV() {
      this.cvv = this.cvv.replace(/\D/g, "").slice(0, 4);
      this.validateCVV();
    },
    validateCardNumber() {
      this.checkoutError = "";
      const cleaned = this.cardNumber.replace(/\s+/g, "");
      if (cleaned.length !== 16) {
        this.cardNumberError = "Enter correct card number";
      } else {
        this.cardNumberError = "";
      }
      this.updateValidationState();
    },
    validateExpiryDate() {
      this.checkoutError = "";
      const [month, year] = this.expiryDate.split("/");
      const currentYear = new Date().getFullYear() % 100;
      const currentMonth = new Date().getMonth() + 1;

      if (!month || !year || month < 1 || month > 12 || year < currentYear || (year == currentYear && month < currentMonth)) {
        this.expiryDateError = "Incorrect expire date";
      } else {
        this.expiryDateError = "";
      }
      this.updateValidationState();
    },
    validateCVV() {
      this.checkoutError = "";
      if (this.cvv.length < 3 || this.cvv.length > 4) {
        this.cvvError = "CVV must contain 3-4 numbers";
      } else {
        this.cvvError = "";
      }
      this.updateValidationState();
    },
    updateValidationState() {
      this.valid = !this.cardNumberError && !this.expiryDateError && !this.cvvError;
    },
    handleSubmit() {
      this.validateCardNumber();
      this.validateExpiryDate();
      this.validateCVV();

      if (!this.valid) return;
      try {
        const cardData = {
          card_number: this.cardNumber.replace(/\s+/g, ""),
          expiry_date: this.expiryDate,
          cvv2: this.cvv,
          amount: this.amount,
          merchant_id: 1549901,
          currency: 'GEL',
          payment_system: "card",
        };
        const that = this
        $checkout('Api').scope(function () {
          this.request('api.checkout.form', 'request', cardData).done(function (model) {
            that.$router.push('/payment');
          }).fail(function (model) {
            that.checkoutError = model.attr('error').message;
          });
        });
      } catch (error) {
        alert("An error occurred. Please check your details.");
      }
    },
  },
};
</script>

<style scoped>
.c-simple-card {
    max-width: 490px !important;
    margin: auto;
}
@media screen and (max-width: 540px) {
  .c-button-list {
    overflow-x: scroll;
  }
  .c-simple-card {
    max-width: 420px !important;
  }
}

@media screen and (max-width: 470px) {
  .v-container {
    padding: 0 !important;
  }
  .v-card-text {
    padding: 5px !important;
    padding-bottom: 10px !important;
  }
  .c-simple-card {
    max-width: 320px !important;
    padding: 0!important;
  }
}


</style>